import sys, io, os
try:
	input = io.BytesIO(os.read(0, os.fstat(0).st_size)).readline
except:
	input = lambda : sys.stdin.readline().encode()
read = lambda : map(int, input().split())
from collections import defaultdict as dd
O = []
for _ in range(int(input())):
	(n, q) = read()
	s = input().strip()
	p = [[0], [0]]
	for i in range(n):
		p[i & 1].append(p[i & 1][-1] + 44 - s[i])
	for i in range(q):
		(l, r) = read()
		L = [l // 2, (l - 1) // 2]
		R = [(r + 1) // 2, r // 2]
		if l - r & 1:
			if p[0][R[0]] - p[0][L[0]] == p[1][R[1]] - p[1][L[1]]:
				O.append('0')
				continue
			else:
				O.append('2')
				l += 1
				L = [l // 2, (l - 1) // 2]
				f = 1
		else:
			O.append('1')
			f = 0
		B = [l, r]
		left = p[1][R[1]] - p[1][l // 2] - (p[0][R[0]] - p[0][(l + 1) // 2])
		if left == 0:
			if f:
				O.append(f'{l - 1} {l}')
			else:
				O.append(f'{l}')
			continue
		right = p[0][r // 2] - p[0][L[0]] - (p[1][(r - 1) // 2] - p[1][L[1]])
		if right == 0:
			if f:
				O.append(f'{l - 1} {r}')
			else:
				O.append(f'{r}')
			continue
		while B[1] - B[0] > 1:
			m = sum(B) // 2
			mid0 = p[0][m // 2] - p[0][L[0]] - (p[0][R[0]] - p[0][(m + 1) // 2])
			mid1 = p[1][(m - 1) // 2] - p[1][L[1]] - (p[1][R[1]] - p[1][m // 2])
			mid = mid0 - mid1
			if mid == 0:
				if f:
					O.append(f'{l - 1} {m}')
				else:
					O.append(f'{m}')
				break
			elif mid > 0:
				if left > 0:
					B[0] = m
					left = mid
				else:
					B[1] = m
					right = mid
			elif left > 0:
				B[1] = m
				right = mid
			else:
				B[0] = m
				left = mid
print('\n'.join(O))
